const wiring={check:(input:any)=>runOperation(checkOp,input).pipe(Effect.map(e=>({exit:exitCodeForEnvelope(e),data:e.data as unknown}))), solver:solverServiceLayer}
const base=fixtureDoc('base.json');const out:any[]=[]
const waivers:any[]=[
 {label:'dual-scope',code:'GTWR_R5_INDEFINITE_ARTICLE',requirementId:ID['LOG-R2'],requirementIds:[ID['LOG-R1']],contentHash:HASH['LOG-R1'],reason:'reviewed only the intersection'},
 {label:'whitespace-code',code:' FND_CONTRADICTION ',reason:'old writer'},
 {label:'missing-single-id',code:'GTWR_R5_INDEFINITE_ARTICLE',requirementId:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',contentHash:HASH['LOG-R1'],reason:'deleted requirement'},
 {label:'blank-reason',code:'GTWR_R5_INDEFINITE_ARTICLE',requirementIds:[ID['LOG-R1']],contentHash:HASH['LOG-R1'],reason:'   '},
]
for(const {label,...waiver} of waivers){
 const doc=Schema.decodeUnknownSync(RequirementsDocument)({...base,waivers:[waiver]})
 const run=await checkDocument(wiring,doc)
 const rawOp={op:'waive',code:waiver.code,reason:waiver.reason,...(waiver.requirementId===undefined?{}:{ref:waiver.requirementId}),...(waiver.requirementIds===undefined?{}:{refs:waiver.requirementIds}),...(waiver.contentHash===undefined?{}:{contentHash:waiver.contentHash})}
 const op=Effect.runSync(decodeOp(rawOp));const applied=applyOp(base,op,'2026-10-05T00:00:00.000Z',MUTATE_OPTIONS)
 const diagnostics=run.data.diagnostics.filter(d=>d.kind==='waiver-inert')
 const replacements=diagnostics.flatMap(d=>d.ops??[])
 const folded=foldOps(doc,replacements.map(o=>Effect.runSync(decodeOp(o))),'2026-10-05T00:00:00.000Z',MUTATE_OPTIONS)
 const result={label,schemaAccepted:true,waiver,standing:waiverStanding(doc,doc.waivers[0]!),forwarded:toEngineDoc(doc).waivers,apply:('code' in applied?applied:{noop:applied.noop}),check:{exit:run.exit,waived:run.data.waived,verified:run.data.verified,appliedWaivers:run.data.appliedWaivers,diagnostics},replacementResult:{write:folded.write,results:folded.results,waiversRemaining:folded.document.waivers}}
 out.push(result);console.log(JSON.stringify(result))
}
writeFileSync(new URL('../../probes.json',import.meta.url),JSON.stringify(out,null,2)+'\n')

